static void Append(NSMutableString *out,id value,NSUInteger depth){if(out.length>12000||depth>8)return;if([value isKindOfClass:NSDictionary.class]){for(NSString *k in [[value allKeys] sortedArrayUsingSelector:@selector(compare:)]){if([@[@"sha256",@"digest",@"runtimeValidated",@"modified"] containsObject:k])continue;id v=value[k];if([v isKindOfClass:NSArray.class]&&![v count])continue;[out appendFormat:@"%@%@：",out.length?@"\n":@"",Label(k)];Append(out,v,depth+1);}}else if([value isKindOfClass:NSArray.class]){for(id v in value){[out appendString:@"\n• "];Append(out,v,depth+1);}}else if([value isKindOfClass:NSString.class])[out appendString:value];else if([value isKindOfClass:NSNumber.class])[out appendString:[value description]];else if(value&&value!=NSNull.null)[out appendString:[value description]];}
