NSString *TFAIActivityDetail(NSDictionary *r){
 NSMutableString *out=[NSMutableString new];NSDictionary *a=[r[@"arguments"] isKindOfClass:NSDictionary.class]?r[@"arguments"]:@{};id result=r[@"result"];
 if([result isKindOfClass:NSString.class]){NSData *d=[result dataUsingEncoding:NSUTF8StringEncoding];id parsed=d?[NSJSONSerialization JSONObjectWithData:d options:0 error:nil]:nil;if([parsed isKindOfClass:NSDictionary.class]||[parsed isKindOfClass:NSArray.class])result=parsed;}
 NSString *path=S(a[@"path"]);if(!path.length&&[result isKindOfClass:NSDictionary.class])path=S(result[@"path"]);
 if(path.length)[out appendString:path];if(a[@"start_line"])[out appendFormat:@" · 第 %@ 行起",a[@"start_line"]];if(S(a[@"query"]).length)[out appendFormat:@"%@搜索：%@",out.length?@"\n":@"",a[@"query"]];
 if([result isKindOfClass:NSDictionary.class]){NSMutableDictionary *fields=[result mutableCopy];if([S(fields[@"path"]) isEqual:path])[fields removeObjectForKey:@"path"];
 NSString *source=S(fields[@"text"]);NSString *sourceKey=@"text";if(!source.length){source=S(fields[@"content"]);sourceKey=@"content";}
 if(source.length){[out appendFormat:@"%@%@",out.length?@"\n\n":@"",source];[fields removeObjectForKey:sourceKey];}
 if(fields.count){if(out.length)[out appendString:@"\n"];Append(out,fields,0);}
 }else if(result){if(out.length)[out appendString:@"\n\n"];Append(out,result,0);}
 if(S(r[@"summary"]).length)[out appendFormat:@"\n%@",r[@"summary"]];if(!out.length)[out appendString:@"等待工具返回结果…"];
 if(out.length>12000)[out deleteCharactersInRange:NSMakeRange(12000,out.length-12000)];return [out stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
